describe('Image Alt Text Accessibility', () => {
  beforeEach(() => {
    cy.visit('/images');
  });

  it('should display descriptive alt text for all images', () => {
    // Verify the first image has descriptive alt text
    cy.get('[alt="A photo of a golden retriever playing in a park"]').should('be.visible');
    cy.get('[alt="A photo of a golden retriever playing in a park"]').should('have.attr', 'alt');
    cy.get('[alt="A photo of a golden retriever playing in a park"]').should('contain', 'golden retriever');

    // Verify the second image has descriptive alt text
    cy.get('[alt="A close-up of a steaming cup of coffee"]').should('be.visible');
    cy.get('[alt="A close-up of a steaming cup of coffee"]').should('have.attr', 'alt');
    cy.get('[alt="A close-up of a steaming cup of coffee"]').should('contain', 'coffee');

    // Verify the third image has descriptive alt text
    cy.get('[alt="A abstract watercolor painting of a mountain landscape"]').should('be.visible');
    cy.get('[alt="An abstract watercolor painting of a mountain landscape"]').should('have.attr', 'alt');
    cy.get('[alt="An abstract watercolor painting of a mountain landscape"]').should('contain', 'mountain');

    // Verify all images have alt attributes
    cy.get('[alt]').should('have.length.greaterThan', 0);
  });

  it('should handle empty alt text for decorative images', () => {
    // Verify decorative image has empty alt text
    cy.get('[alt=""]').should('be.visible');
    cy.get('[alt=""]').should('have.attr', 'alt', '');

    // Verify image with no alt attribute is not present
    cy.get('[alt=""]').should('not.exist');

    // Verify image with descriptive alt text is still present
    cy.get('[alt="A photo of a golden retriever playing in a park"]').should('be.visible');
    cy.get('[alt="A photo of a golden retriever playing in a park"]').should('have.attr', 'alt');
  });
});
